/**
 * withPodfileResourceBundleSigning — fix Xcode 14+ resource-bundle signing.
 *
 * Xcode 14+ code-signs CocoaPods *resource-bundle* targets by default. On EAS
 * these bundle targets have no development team, so the build fails with:
 *
 *   "Signing for "<Pod>-<Pod>" requires a development team.
 *    Starting from Xcode 14, resource bundles are signed by default..."
 *
 * Fix: disable code signing ONLY for resource-bundle targets. The main app
 * target and frameworks keep normal signing. Critically, this loop must run
 * AFTER `react_native_post_install(...)` (which re-materialises target build
 * settings), otherwise the change can be reverted. We therefore inject right
 * after that call inside the existing `post_install` block.
 *
 * The `ios/` folder is regenerated by Expo prebuild on every EAS build, so a
 * manual Podfile edit would be wiped — this plugin re-applies it each time.
 */

const { withDangerousMod } = require('@expo/config-plugins');
const fs = require('fs');
const path = require('path');

const MARKER = '# withPodfileResourceBundleSigning — Xcode14 resource-bundle signing fix';

// Two complementary passes for maximum coverage across CocoaPods versions:
//  1) Every target whose product type is a bundle.
//  2) The authoritative resource_bundle_targets from installation results.
const INJECTION = `
    ${MARKER}
    installer.pods_project.targets.each do |__rb_target|
      if __rb_target.respond_to?(:product_type) && __rb_target.product_type == 'com.apple.product-type.bundle'
        __rb_target.build_configurations.each do |__rb_config|
          __rb_config.build_settings['CODE_SIGNING_ALLOWED'] = 'NO'
          __rb_config.build_settings['CODE_SIGNING_REQUIRED'] = 'NO'
          __rb_config.build_settings['CODE_SIGN_IDENTITY'] = ''
          __rb_config.build_settings['EXPANDED_CODE_SIGN_IDENTITY'] = ''
        end
      end
    end
    if installer.respond_to?(:target_installation_results)
      installer.target_installation_results.pod_target_installation_results.each do |__rb_name, __rb_result|
        next unless __rb_result.respond_to?(:resource_bundle_targets)
        __rb_result.resource_bundle_targets.each do |__rb_bundle|
          __rb_bundle.build_configurations.each do |__rb_config|
            __rb_config.build_settings['CODE_SIGNING_ALLOWED'] = 'NO'
            __rb_config.build_settings['CODE_SIGNING_REQUIRED'] = 'NO'
            __rb_config.build_settings['CODE_SIGN_IDENTITY'] = ''
            __rb_config.build_settings['EXPANDED_CODE_SIGN_IDENTITY'] = ''
          end
        end
      end
    end
`;

module.exports = function withPodfileResourceBundleSigning(config) {
  return withDangerousMod(config, [
    'ios',
    (cfg) => {
      const podfilePath = path.join(cfg.modRequest.platformProjectRoot, 'Podfile');
      let contents = fs.readFileSync(podfilePath, 'utf8');

      // Idempotent.
      if (contents.includes(MARKER)) {
        return cfg;
      }

      // Preferred: inject immediately AFTER the react_native_post_install(...)
      // call so our settings win over anything that call applies.
      const rnPostInstall = /react_native_post_install\([\s\S]*?\)\n/;
      if (rnPostInstall.test(contents)) {
        contents = contents.replace(rnPostInstall, (match) => `${match}${INJECTION}`);
      } else {
        const postInstallOpen = /post_install do \|installer\|[^\n]*\n/;
        if (postInstallOpen.test(contents)) {
          // Fallback: inject at the start of the post_install block.
          contents = contents.replace(postInstallOpen, (match) => `${match}${INJECTION}`);
        } else {
          // No post_install anywhere — append a dedicated block.
          contents += `\npost_install do |installer|${INJECTION}end\n`;
        }
      }

      fs.writeFileSync(podfilePath, contents);
      return cfg;
    },
  ]);
};
